import{_ as e,C as t,c as a,o as i,a0 as o,b as n,w as l,a as r,G as s,a1 as u}from"./chunks/framework.DKRgXLPU.js";const h=JSON.parse('{"title":"Team Communication","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/team-player/communication.md","filePath":"en/education/team-player/communication.md"}');const c=e({name:"en/education/team-player/communication.md"},[["render",function(e,h,c,d,m,g){const p=t("Mermaid");return i(),a("div",null,[h[1]||(h[1]=o('<h1 id="team-communication" tabindex="-1">Team Communication <a class="header-anchor" href="#team-communication" aria-label="Permalink to &quot;Team Communication&quot;">​</a></h1><p>Effective communication is what transforms a group of individuals into a team. In pétanque, where strategy shifts constantly and pressure runs high, how you communicate can determine the outcome.</p><div class="tip custom-block"><p class="custom-block-title">The Big Idea</p><p><strong>Communication is what transforms individuals into a team.</strong> Clear, specific, and supportive communication under pressure separates good teams from great ones.</p></div><h2 id="the-communication-cycle" tabindex="-1">The Communication Cycle <a class="header-anchor" href="#the-communication-cycle" aria-label="Permalink to &quot;The Communication Cycle&quot;">​</a></h2><p>Good team communication follows a cycle:</p>',5)),(i(),n(u,null,{default:l(()=>[s(p,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObserve%5D%20--%3E%20B%5BShare%5D%0A%20%20%20%20B%20--%3E%20C%5BDiscuss%5D%0A%20%20%20%20C%20--%3E%20D%5BDecide%5D%0A%20%20%20%20D%20--%3E%20E%5BExecute%5D%0A%20%20%20%20E%20--%3E%20F%5BReview%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:l(()=>[...h[0]||(h[0]=[r(" Loading... ",-1)])]),_:1})),h[2]||(h[2]=o('<table tabindex="0"><thead><tr><th>Step</th><th>Action</th><th>Example</th></tr></thead><tbody><tr><td><strong>Observe</strong></td><td>Notice what&#39;s happening</td><td>Terrain, positions, opponents</td></tr><tr><td><strong>Share</strong></td><td>Tell teammates what you see</td><td>&quot;The ground slopes left there&quot;</td></tr><tr><td><strong>Discuss</strong></td><td>Exchange perspectives</td><td>&quot;Should I block or go for point?&quot;</td></tr><tr><td><strong>Decide</strong></td><td>Agree on approach</td><td>&quot;Let&#39;s try the high lob&quot;</td></tr><tr><td><strong>Execute</strong></td><td>Do it with commitment</td><td>Full focus on the throw</td></tr><tr><td><strong>Review</strong></td><td>Learn from result</td><td>&quot;That worked well&quot; or &quot;Next time...&quot;</td></tr></tbody></table><h2 id="when-to-communicate" tabindex="-1">When to Communicate <a class="header-anchor" href="#when-to-communicate" aria-label="Permalink to &quot;When to Communicate&quot;">​</a></h2><h3 id="before-each-end" tabindex="-1">Before Each End <a class="header-anchor" href="#before-each-end" aria-label="Permalink to &quot;Before Each End&quot;">​</a></h3><ul><li>Assess the terrain together</li><li>Discuss general approach</li><li>Clarify who&#39;s throwing when</li><li>Set the tone (calm, focused)</li></ul><h3 id="during-the-end" tabindex="-1">During the End <a class="header-anchor" href="#during-the-end" aria-label="Permalink to &quot;During the End&quot;">​</a></h3><ul><li>Share observations (&quot;The ground slopes left there&quot;)</li><li>Coordinate strategy (&quot;Should I try to block or go for the point?&quot;)</li><li>Offer support (&quot;Take your time, you&#39;ve got this&quot;)</li><li>Adjust plans as situation changes</li></ul><h3 id="between-ends" tabindex="-1">Between Ends <a class="header-anchor" href="#between-ends" aria-label="Permalink to &quot;Between Ends&quot;">​</a></h3><ul><li>Quick debrief (what worked, what didn&#39;t)</li><li>Reset mentally</li><li>Prepare for next end</li><li>Stay connected as a team</li></ul><h3 id="after-the-game" tabindex="-1">After the Game <a class="header-anchor" href="#after-the-game" aria-label="Permalink to &quot;After the Game&quot;">​</a></h3><ul><li>Full debrief (when appropriate)</li><li>Acknowledge contributions</li><li>Identify learnings</li><li>Maintain relationship</li></ul><h2 id="how-to-communicate" tabindex="-1">How to Communicate <a class="header-anchor" href="#how-to-communicate" aria-label="Permalink to &quot;How to Communicate&quot;">​</a></h2><h3 id="be-clear-and-specific" tabindex="-1">Be Clear and Specific <a class="header-anchor" href="#be-clear-and-specific" aria-label="Permalink to &quot;Be Clear and Specific&quot;">​</a></h3><p><strong>Vague:</strong> &quot;Try to get close&quot; <strong>Clear:</strong> &quot;Aim for the left side of the jack, about 20cm out&quot;</p><p><strong>Vague:</strong> &quot;Nice try&quot; <strong>Clear:</strong> &quot;Good weight, just a bit left of line&quot;</p><h3 id="be-constructive" tabindex="-1">Be Constructive <a class="header-anchor" href="#be-constructive" aria-label="Permalink to &quot;Be Constructive&quot;">​</a></h3><p>Focus on solutions, not problems:</p><p><strong>Problem-focused:</strong> &quot;You keep missing to the right&quot; <strong>Solution-focused:</strong> &quot;Maybe try aiming a bit more left to compensate?&quot;</p><h3 id="be-supportive" tabindex="-1">Be Supportive <a class="header-anchor" href="#be-supportive" aria-label="Permalink to &quot;Be Supportive&quot;">​</a></h3><p>Your tone matters as much as your words:</p><ul><li>Stay calm, even when frustrated</li><li>Use encouraging body language</li><li>Acknowledge effort, not just results</li><li>Build up, don&#39;t tear down</li></ul><h3 id="listen-actively" tabindex="-1">Listen Actively <a class="header-anchor" href="#listen-actively" aria-label="Permalink to &quot;Listen Actively&quot;">​</a></h3><p>Communication is two-way:</p><ul><li>Give full attention when teammates speak</li><li>Ask clarifying questions</li><li>Acknowledge what you&#39;ve heard</li><li>Don&#39;t interrupt or dismiss</li></ul><h2 id="communication-challenges" tabindex="-1">Communication Challenges <a class="header-anchor" href="#communication-challenges" aria-label="Permalink to &quot;Communication Challenges&quot;">​</a></h2><h3 id="disagreement-on-strategy" tabindex="-1">Disagreement on Strategy <a class="header-anchor" href="#disagreement-on-strategy" aria-label="Permalink to &quot;Disagreement on Strategy&quot;">​</a></h3><p><strong>Poor approach:</strong></p><ul><li>Insist on your way</li><li>Get defensive</li><li>Give in resentfully</li><li>Argue during the game</li></ul><p><strong>Better approach:</strong></p><ol><li>Share your perspective clearly</li><li>Listen to theirs fully</li><li>Discuss pros and cons briefly</li><li>Decide together (or defer to designated leader)</li><li>Commit fully to the decision</li><li>Review after the game</li></ol><h3 id="after-a-teammate-s-mistake" tabindex="-1">After a Teammate&#39;s Mistake <a class="header-anchor" href="#after-a-teammate-s-mistake" aria-label="Permalink to &quot;After a Teammate&#39;s Mistake&quot;">​</a></h3><p><strong>What they need:</strong></p><ul><li>Quick acknowledgment</li><li>Permission to move on</li><li>Confidence that you still trust them</li><li>Focus on the next throw</li></ul><p><strong>What to say:</strong></p><ul><li>&quot;No problem, next one&quot;</li><li>&quot;Tough break, you&#39;ve got the next&quot;</li><li>&quot;We&#39;re still in this&quot;</li><li><em>Sometimes just a nod or pat is enough</em></li></ul><p><strong>What NOT to say:</strong></p><ul><li>Nothing (silence feels like judgment)</li><li>&quot;It&#39;s okay&quot; (can sound dismissive)</li><li>Anything about what went wrong (not now)</li><li>Visible frustration (body language counts)</li></ul><h3 id="when-you-make-a-mistake" tabindex="-1">When You Make a Mistake <a class="header-anchor" href="#when-you-make-a-mistake" aria-label="Permalink to &quot;When You Make a Mistake&quot;">​</a></h3><p><strong>What to do:</strong></p><ul><li>Brief acknowledgment (&quot;My bad&quot;)</li><li>Don&#39;t over-apologize</li><li>Don&#39;t make excuses</li><li>Reset and focus on next throw</li><li>Trust your teammates to support you</li></ul><h3 id="tension-in-the-team" tabindex="-1">Tension in the Team <a class="header-anchor" href="#tension-in-the-team" aria-label="Permalink to &quot;Tension in the Team&quot;">​</a></h3><p>If tension builds during a game:</p><ol><li>Recognize it&#39;s happening</li><li>Take a breath before responding</li><li>Focus on the game, not the conflict</li><li>Address it properly after the game</li><li>Don&#39;t let it affect your play</li></ol><h2 id="non-verbal-communication" tabindex="-1">Non-Verbal Communication <a class="header-anchor" href="#non-verbal-communication" aria-label="Permalink to &quot;Non-Verbal Communication&quot;">​</a></h2><p>Much of team communication is non-verbal:</p><h3 id="positive-signals" tabindex="-1">Positive Signals <a class="header-anchor" href="#positive-signals" aria-label="Permalink to &quot;Positive Signals&quot;">​</a></h3><ul><li>Eye contact</li><li>Nodding</li><li>Thumbs up</li><li>Relaxed posture</li><li>Moving toward teammates</li><li>Smiling (when appropriate)</li></ul><h3 id="negative-signals-avoid-these" tabindex="-1">Negative Signals (Avoid These) <a class="header-anchor" href="#negative-signals-avoid-these" aria-label="Permalink to &quot;Negative Signals (Avoid These)&quot;">​</a></h3><ul><li>Eye rolling</li><li>Turning away</li><li>Crossed arms</li><li>Sighing</li><li>Shaking head</li><li>Tense body language</li></ul><p><strong>Remember:</strong> Your teammates see everything. Your body language affects their confidence and performance.</p><h2 id="building-communication-habits" tabindex="-1">Building Communication Habits <a class="header-anchor" href="#building-communication-habits" aria-label="Permalink to &quot;Building Communication Habits&quot;">​</a></h2><h3 id="practice-communication" tabindex="-1">Practice Communication <a class="header-anchor" href="#practice-communication" aria-label="Permalink to &quot;Practice Communication&quot;">​</a></h3><p>Don&#39;t wait for competition to communicate:</p><ul><li>Practice strategic discussions in training</li><li>Give each other feedback regularly</li><li>Develop your team language</li><li>Build comfort with honest conversation</li></ul><h3 id="develop-team-signals" tabindex="-1">Develop Team Signals <a class="header-anchor" href="#develop-team-signals" aria-label="Permalink to &quot;Develop Team Signals&quot;">​</a></h3><p>Some teams develop shorthand:</p><ul><li>Hand signals for strategy</li><li>Code words for situations</li><li>Quick phrases with shared meaning</li></ul><h3 id="regular-check-ins" tabindex="-1">Regular Check-ins <a class="header-anchor" href="#regular-check-ins" aria-label="Permalink to &quot;Regular Check-ins&quot;">​</a></h3><p>Outside of games:</p><ul><li>How are we working together?</li><li>What&#39;s going well?</li><li>What could be better?</li><li>Any issues to address?</li></ul><h2 id="the-captain-s-role" tabindex="-1">The Captain&#39;s Role <a class="header-anchor" href="#the-captain-s-role" aria-label="Permalink to &quot;The Captain&#39;s Role&quot;">​</a></h2><p>If your team has a designated leader:</p><p><strong>Captain responsibilities:</strong></p><ul><li>Final decision when team disagrees</li><li>Setting the tone and energy</li><li>Managing team dynamics</li><li>Keeping focus during pressure</li></ul><p><strong>Everyone else:</strong></p><ul><li>Share your perspective</li><li>Support the decision once made</li><li>Help maintain team energy</li><li>Take responsibility for your role</li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>Great teams talk to each other, not about each other. They communicate with honesty, respect, and a shared commitment to success.</p></blockquote><p>Practice communication like you practice throwing. It&#39;s a skill that improves with attention.</p>',68))])}]]);export{h as __pageData,c as default};
